// Code node "Shape email". One item per new inbox email (IMAP, format resolved).
// Robots (no-reply senders, bulk mail, list mail) are labeled noise without asking the local AI.
const ME = /grahamivy\.co@gmail\.com|@openframe\.design/i;
const ROBOT = /(no-?reply|donotreply|do-not-reply|mailer-daemon|postmaster|notifications?@|notify@|alerts?@|news(letter)?@|marketing@|updates?@|digest@)/i;
const OPTOUT = /\b(unsubscribe me|remove me from|stop (emailing|contacting|sending)|take me off|please don'?t (email|contact) me)\b/i;
const head = (j, k) => {
  const h = j.headers || {};
  if (h[k] != null) return String(h[k].value || h[k].text || h[k]);
  const line = (j.headerLines || []).find(x => String(x.key).toLowerCase() === k);
  return line ? String(line.line) : '';
};
const clean = s => String(s || '').replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();
const strip = h => String(h || '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li)>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');

return $input.all().map(i => {
  const j = i.json;
  const from = (j.from && j.from.value && j.from.value[0]) || {};
  const email = String(from.address || (String(j.from && j.from.text || j.from || '').match(/[^\s<>]+@[^\s<>]+/) || [''])[0]).toLowerCase();
  const name = String(from.name || '').replace(/"/g, '').trim();
  const text = clean(j.text || strip(j.html || j.textHtml));
  // Drop the quoted thread under "On ... wrote:" so the AI reads only the new part.
  const fresh = text.split(/\n\s*On .{5,120}wrote:\s*\n|\n-{2,}\s*Original Message/i)[0].slice(0, 3000);
  const bulk = /bulk|list|junk/i.test(head(j, 'precedence')) || !!head(j, 'list-unsubscribe') || !!head(j, 'list-id');
  const robot = ROBOT.test(email) || bulk;
  const calendly = /@calendly\.com$/i.test(email);
  return { json: {
    message_id: String(j.messageId || head(j, 'message-id') || '').trim(),
    received_at: new Date(j.date || Date.now()).toISOString(),
    from_email: email, from_name: name, subject: String(j.subject || '').slice(0, 200),
    snippet: fresh.slice(0, 600), body: fresh,
    mine: ME.test(email),
    // Calendly booking emails are read by the lead follow-up workflow; here they're just filed.
    fixed_type: calendly ? 'admin' : robot ? 'noise' : '',
    optout: !robot && OPTOUT.test(fresh.slice(0, 600)),
  } };
}).filter(i => i.json.message_id && !i.json.mine);

// Code node "Robot row". Noise and Calendly mail skip the AI.
const now = new Date().toISOString();
return $input.all().map(i => { const e = i.json; return { json: {
  message_id: e.message_id, received_at: e.received_at, from_email: e.from_email, from_name: e.from_name, subject: e.subject,
  snippet: e.snippet.slice(0, 200), type: e.fixed_type, needs_reply: 'no', draft: '', optout: 'no', status: 'new', draft_id: '', note: '', updated_at: now,
} }; });

// Code node "Build AI request". LM Studio on Graham's Mac (free, local). Same model as the DM bot.
const SYSTEM = `You sort email for Graham Ivy, who runs Open Frame, a small design and marketing studio for mission-driven organizations and brands (Minneapolis and Barcelona, available US hours).
Pick one type:
- lead: someone asking about working with Open Frame, its services, prices, availability, or a project
- client: an existing client talking about ongoing work
- money: invoices, receipts, payments, bank, taxes, subscriptions billing
- admin: accounts, scheduling, tools, platform or legal notices addressed to Graham personally
- personal: friends and family, nothing about the business
- noise: newsletters, promotions, cold sales pitches, automated notifications
needs_reply: true only if a person is waiting on Graham.
reply: only for lead or client when needs_reply is true, otherwise "". Write as Graham, warm and plain, under 90 words, then a blank line and "Graham".
Reply rules: never give prices, dates, deadlines or promises; never invent facts or links. For a lead, offer a free 30-minute call with this link on its own line after a blank line:

https://calendly.com/grahamivy-co/30min

No em dashes, no hype words. If you are unsure what to say, reply "" so Graham writes it himself.`;
const SCHEMA = { type: 'object', additionalProperties: false, required: ['type', 'needs_reply', 'reply'],
  properties: { type: { type: 'string', enum: ['lead', 'client', 'money', 'admin', 'personal', 'noise'] }, needs_reply: { type: 'boolean' }, reply: { type: 'string' } } };
return $input.all().map(i => ({ json: Object.assign({}, i.json, { ai: {
  model: 'qwen/qwen3.5-9b', reasoning_effort: 'none', chat_template_kwargs: { enable_thinking: false }, temperature: 0.3, max_tokens: 400,
  messages: [{ role: 'system', content: SYSTEM },
    { role: 'user', content: `From: ${i.json.from_name} <${i.json.from_email}>\nSubject: ${i.json.subject}\n\n${i.json.body}` }],
  response_format: { type: 'json_schema', json_schema: { name: 'triage', strict: true, schema: SCHEMA } },
} }) }));

// Code node "Read answer". Turns the local AI's answer into a Mail tab row. A reply that breaks a rule is dropped,
// so the card asks Graham to write it himself instead of sending something wrong.
const OK_LINK = /^https:\/\/(calendly\.com\/grahamivy-co\/30min|openframe\.design)/;
const now = new Date().toISOString();
const ins = $('Build AI request').all();
return $input.all().map((i, n) => {
  const e = (ins[n] || ins[0]).json;
  let a = {};
  try { a = JSON.parse(i.json.choices[0].message.content); } catch (x) { a = { type: 'check', needs_reply: false, reply: '' }; }
  let reply = String(a.reply || '').replace(/\s*[—–]\s*/g, ', ').trim();
  const links = reply.match(/https?:\/\/\S+/g) || [];
  const broke = /\$\s?\d|\d+\s?(usd|dollars)/i.test(reply) || links.some(u => !OK_LINK.test(u));
  if (broke || !['lead', 'client'].includes(a.type) || !a.needs_reply) reply = '';
  return { json: {
    message_id: e.message_id, received_at: e.received_at, from_email: e.from_email, from_name: e.from_name, subject: e.subject,
    snippet: e.snippet, type: a.type || 'check', needs_reply: a.needs_reply ? 'yes' : 'no', draft: reply,
    optout: e.optout ? 'yes' : 'no', status: 'new', draft_id: '', note: broke ? 'AI reply broke a rule, write your own' : '', updated_at: now,
  } };
});
